function y({registerIndicator:b,nulls:h}){b({id:"oa-lrsi",name:"LRSI: Laguerre RSI",category:"Oscillators",placement:"pane",inputs:[{key:"gamma",type:"number",label:"Gamma",default:.5,min:0,max:1,step:.01,tooltip:"Damping factor [0,1]. Lower = more responsive; higher = smoother."}],plots:[{key:"lrsi",type:"line",title:"LRSI",style:{color:"#ffeb3b",lineWidth:2}}],levels(){return[{price:.8,title:"Overbought",color:"#f23645"},{price:.5,title:"Midline",color:"#787b86"},{price:.2,title:"Oversold",color:"#089981"}]},calc(n,L){const c=n.length,a=Number(L.gamma),l=Math.min(1,Math.max(0,Number.isFinite(a)?a:.5)),m=new Array(c).fill(NaN);let o=0,e=0,t=0,r=0;for(let i=0;i<c;i++){const d=Number.isFinite(n[i].close)?n[i].close:0,p=o,u=e,f=t;o=(1-l)*d+l*p,e=-l*o+p+l*u,t=-l*e+u+l*f,r=-l*t+f+l*r;const g=(o>e?o-e:0)+(e>t?e-t:0)+(t>r?t-r:0),v=(o<e?e-o:0)+(e<t?t-e:0)+(t<r?r-t:0),s=g+v;m[i]=s!==0&&Number.isFinite(s)?g/s:.5}return{lrsi:h(m)}}})}export{y as default};
